<template>
  <el-main>
    <el-row justify="end">
      <el-button type="primary" @click="addInvoice">New invoice</el-button>
    </el-row>
    <el-table :data="tableData" :default-sort="{ prop: 'date', order: 'descending' }" style="width: 100%">
      <el-table-column prop="description" label="Description" width="320">
      </el-table-column>
      <el-table-column label="Reference" width="150">
        <template #default="scope">
          <a href="" @click.prevent="print(scope.row)">{{
            scope.row.reference
          }}</a>
        </template>
      </el-table-column>
      <el-table-column label="Date" prop="date" width="180">
        <template #default="scope">
          {{ formatDate(scope.row.date) }}
        </template>
      </el-table-column>
      <el-table-column label="Client">
        <template #default="scope">
          {{ clientDescription(scope.row.client) }}
        </template>
      </el-table-column>
      <el-table-column label="Total" width="100">
        <template #default="scope">
          {{ invoiceTotal(scope.row) }}
        </template>
      </el-table-column>
      <el-table-column prop="paid" label="Paid" width="90" align="center" :filters="[
        { text: 'Paid', value: true },
        { text: 'Unpaid', value: false },
      ]" :filter-method="filterPaid" :filtered-value="[false]">
        <template #default="scope">
          <el-checkbox v-model="scope.row.paid" />
        </template>
      </el-table-column>
      <el-table-column align="right">
        <template #header>
          <el-input v-model="search" placeholder="Type to search" />
        </template>
        <template #default="scope">
          <el-button :icon="Edit" circle @click="handleEdit(scope.row)" />
          <el-button :icon="Delete" circle @click="deleteInvoice(scope.row.id)" />
        </template>
      </el-table-column>
    </el-table>

    <el-dialog v-model="dialogVisible" width="80%">
      <template #title>
        <span style="margin-right: 30px"> {{ editInvoice.reference }}</span>
        <el-checkbox label="Paid" v-model="editInvoice.paid" />
      </template>
      <el-form v-if="editInvoice" label-width="120px">
        <el-form-item label="Description">
          <el-input v-model="editInvoice.description" />
        </el-form-item>
        <el-form-item label="Their reference">
          <el-input v-model="editInvoice.theirReference" />
        </el-form-item>
        <el-form-item label="Job date(s)">
          <el-date-picker v-model="editInvoice.jobDates" type="dates" />
        </el-form-item>
        <el-form-item label="Invoice date">
          <el-date-picker v-model="editInvoice.date" type="date" />
        </el-form-item>
        <el-form-item label="Client">
          <el-select v-model="editInvoice.client" placeholder="Select">
            <el-option v-for="item in clientOptions" :key="item.value" :label="item.label" :value="item.value">
            </el-option>
          </el-select>
        </el-form-item>
        <el-form-item label="Bank">
          <el-select v-model="editInvoice.paymentMethod">
            <el-option label="French" value="French" />
            <el-option label="UK" value="UK" />
          </el-select>
        </el-form-item>
        <el-form-item label="Payment terms">
          <el-input type="number" step="15" max="60" :input-style="{ width: '215px' }"
            v-model="editInvoice.paymentTermsDays" />
        </el-form-item>
        <el-form-item label="VAT">
          <el-checkbox v-model="editInvoice.includeVat" />
        </el-form-item>
        <el-table :data="editInvoice.items" style="width: 100%" empty-text="No items to invoice">
          <el-table-column prop="description">
            <template #default="scope">
              <el-input v-model="scope.row.description" placeholder="Description" />
            </template>
          </el-table-column>
          <el-table-column width="200">
            <template #header>
              <el-button-group>
                <el-button :type="editInvoice.currency === currency ? 'primary' : 'default'
                  " v-for="currency in ['£', '€', '$']" :key="currency" @click="editInvoice.currency = currency">{{
                    currency }}</el-button>
              </el-button-group>
            </template>
            <template #default="scope">
              <div style="display: flex">
                <el-input-number :precision="2" :controls="false" v-model="scope.row.rate" placeholder="Rate"
                  style="width: 100%" />
              </div>
            </template>
          </el-table-column>

          <el-table-column label="Expense" align="center" width="100">
            <template #default="scope">
              <el-checkbox v-model="scope.row.isExpense" />
            </template>
          </el-table-column>
          <el-table-column align="right" width="100">
            <template #header>
              <el-button type="primary" @click="
                editInvoice.items.push({
                  description: '',
                  rate: undefined,
                  isExpense: editInvoice.items.length > 0,
                })
                ">
                Add item
              </el-button>
            </template>
            <template #default="scope">
              <el-button :icon="Delete" circle @click="editInvoice.items.splice(scope.$index, 1)" />
            </template>
          </el-table-column>
        </el-table>
      </el-form>
      <template #footer>
        <span class="dialog-footer">
          <el-button @click="cancelEdit">Cancel</el-button>
          <el-button type="primary" @click="confirmEdit">Confirm</el-button>
        </span>
      </template>
    </el-dialog>
  </el-main>
</template>

<script>
import { Edit, Delete } from '@element-plus/icons-vue'

function uuidv4() {
  return ([1e7] + -1e3 + -4e3 + -8e3 + -1e11).replace(/[018]/g, c =>
    (
      c ^
      (crypto.getRandomValues(new Uint8Array(1))[0] & (15 >> (c / 4)))
    ).toString(16)
  );
}
class Invoice {
  constructor(reference, includeVat) {
    this.id = uuidv4();
    this.description = "";
    this.theirReference = "";
    this.jobDates = [];
    this.date = new Date().toISOString().slice(0, 10);
    this.reference = reference;
    this.client = "";
    this.currency = "€";
    this.items = [{ description: "", rate: undefined, isExpense: false }];
    this.paymentTermsDays = 30;
    this.paymentMethod = "French";
    this.includeVat = includeVat;
    this.paid = false;
  }
}

export default {
  name: "Invoices",
  props: {
    state: Object
  },
  data() {
    return {
      Edit,
      Delete,
      dialogVisible: false,
      editInvoice: false,
      search: ""
    };
  },
  computed: {
    invoices() {
      return this.state.invoices;
    },
    tableData() {
      return this.invoices.filter(
        invoice =>
          !this.search ||
          invoice.description.toLowerCase().includes(this.search.toLowerCase())
      );
    },
    clientOptions() {
      return this.state.clients
        .map(client => {
          let label = client.company || client.name;
          if (client.company && client.name) {
            label += ` (${client.name})`;
          }
          return {
            value: client.id,
            label
          };
        })
        .sort((a, b) => {
          var labelA = a.label.toUpperCase();
          var labelB = b.label.toUpperCase();
          if (labelA < labelB) {
            return -1;
          }
          if (labelA > labelB) {
            return 1;
          }
          return 0;
        });
    }
  },
  methods: {
    getNewReference() {
      let year = new Date()
        .getUTCFullYear()
        .toString()
        .substring(2);
      const prefix = "INV" + year;
      let counter = 1;
      for (var invoice of this.state.invoices) {
        if (invoice.reference.substring(0, prefix.length) == prefix) {
          counter = Math.max(
            counter,
            parseInt(invoice.reference.substring(prefix.length).replaceAll("A", "0")) + 1
          );
        }
      }
      counter = counter.toString();
      while (counter.length < 3) {
        counter = "A" + counter;
      }
      return prefix + counter;
    },
    addInvoice() {
      this.editInvoice = new Invoice(this.getNewReference(), this.state.settings.includeVat);
      this.dialogVisible = true;
    },
    cancelEdit() {
      this.dialogVisible = false;
      this.$nextTick(() => {
        this.editInvoice = false;
      });
    },
    confirmEdit() {
      this.$emit("saveInvoice", this.editInvoice);
      this.cancelEdit();
    },
    handleEdit(invoice) {
      this.editInvoice = JSON.parse(JSON.stringify(invoice));
      this.dialogVisible = true;
    },
    deleteInvoice(id) {
      this.$confirm(
        "This will permanently delete the invoice. Continue?",
        "Warning",
        {
          confirmButtonText: "OK",
          cancelButtonText: "Cancel",
          type: "warning"
        }
      )
        .then(() => {
          this.$emit("deleteInvoice", id);
        })
        .catch(() => {
          // cancelled - don't delete it
        });
    },
    filterPaid(isPaid, invoice) {
      return invoice.paid === isPaid;
    },
    print(invoice) {
      this.$emit("printInvoice", invoice);
    },
    clientDescription(id) {
      let option = this.clientOptions.find(client => client.value === id);
      return option ? option.label : "";
    },
    formatDate(date) {
      return new Date(date).toLocaleDateString("en-GB", {
        year: "numeric",
        month: "long",
        day: "numeric"
      });
    },
    formatCurrency(value) {
      // duplicated from prinatble invoice
      if (parseInt(value) == parseFloat(value)) {
        return value.toString();
      }
      return new Number(value).toFixed(2);
    },
    invoiceTotal(invoice) {
      // duplicated from prinatble invoice
      const reducer = (accumulator, currentValue) =>
        accumulator + Number(currentValue.rate);
      const total = invoice.items.reduce(reducer, 0);
      if (isNaN(total)) {
        return "";
      }
      return invoice.currency + this.formatCurrency(total);
    }
  }
};
</script>

<style scoped></style>
