import {
  addDays,
  compareAsc,
  format,
  isSameDay,
  isSameMonth,
  isSameYear,
} from "date-fns";

function day(date) {
  return String(date.getDate());
}

function month(date, locale) {
  return new Intl.DateTimeFormat(locale, {
    month: "long",
  }).format(date);
}

function and(locale) {
  switch (locale) {
    default: return "and"
    case "fr-FR": return "et"
  }
}

function to(locale) {
  switch (locale) {
    default: return "to"
    case "fr-FR": return "au"
  }
}

function joinNatural(items, locale) {
  if (items.length === 0) return "";
  if (items.length === 1) return items[0];
  if (items.length === 2) return `${items[0]} ${and(locale)} ${items[1]}`;

  return `${items.slice(0, -1).join(", ")} ${and(locale)} ${items.at(-1)}`;
}

function groupConsecutiveDates(dates) {
  if (dates.length === 0) return [];

  const sorted = [...dates]
    .sort(compareAsc)
    .filter((date, i, arr) => i === 0 || !isSameDay(date, arr[i - 1]));

  const ranges = [];

  let start = sorted[0];
  let end = sorted[0];

  for (let i = 1; i < sorted.length; i++) {
    if (isSameDay(sorted[i], addDays(end, 1))) {
      end = sorted[i];
    } else {
      ranges.push({ start, end });
      start = end = sorted[i];
    }
  }

  ranges.push({ start, end });

  return ranges;
}

export function formatDateList(dates, locale) {
  if (dates.length === 0) return "";

  dates = dates.map(d => d instanceof Date ? d : new Date(d));

  const ranges = groupConsecutiveDates(dates);

  const sorted = [...dates].sort(compareAsc);
  const lastDate = sorted.at(-1);

  const months = new Set(
    sorted.map(d => `${d.getFullYear()}-${d.getMonth()}`)
  );

  const years = new Set(
    sorted.map(d => d.getFullYear())
  );

  const multipleMonths = months.size > 1;
  const multipleYears = years.size > 1;

  const body = joinNatural(
    ranges.map(({ start, end }) => {
      if (isSameDay(start, end)) {
        if (multipleYears) {
          return `${day(start)} ${month(start, locale)} ${start.getFullYear()}`;
        }
        if (multipleMonths) {
          return `${day(start)} ${month(start, locale)}`;
        }
        return day(start);
      }

      if (isSameMonth(start, end) && isSameYear(start, end)) {
        if (multipleYears) {
          return `${day(start)} ${to(locale)} ${day(end)} ${month(end, locale)} ${end.getFullYear()}`;
        }
        if (multipleMonths) {
          return `${day(start)} ${to(locale)} ${day(end)} ${month(end, locale)}`;
        }
        return `${day(start)} ${to(locale)} ${day(end)}`;
      }

      if (isSameYear(start, end)) {
        return `${day(start)} ${month(start, locale)} ${to(locale)} ${day(end)} ${month(end, locale)}`;
      }

      return `${day(start)} ${month(start, locale)} ${start.getFullYear()} ${to(locale)} ${day(end)} ${month(end, locale)} ${end.getFullYear()}`;
    }),
    locale
  );

  if (!multipleMonths && !multipleYears) {
    return `${body} ${month(lastDate, locale)} ${lastDate.getFullYear()}`;
  }

  if (!multipleYears) {
    return `${body} ${format(lastDate, "yyyy")}`;
  }

  return body;
}
