<template>
  <div class="page" v-if="state.invoices.length > 0">
    <div style="display: flex; font-size: 24pt; margin-bottom: 60pt">
      <div>{{ labels.invoice }}</div>
      <div style="flex: 1"></div>
      <div>{{ state.settings.businessName }}</div>
    </div>
    <template v-if="invoice">
      <div style="display: flex; font-size: 11pt">
        <div>
          <div>{{ labels.from }}</div>
          <div style="font-size: 16pt">{{ state.settings.name }}</div>
          <div v-if="state.settings.email">{{ state.settings.email }}</div>
          <template v-if="state.settings.address">
            <div v-for="(line, i) in state.settings.address.split(', ')" :key="'adr_' + i">
              {{ line }}
            </div>
          </template>
          <div v-if="state.settings.phone">{{ state.settings.phone }}</div>
          <div v-if="state.settings.siret" style="padding-top: 2em;">SIRET {{ state.settings.siret }}</div>
          <div v-if="!invoice.includeVat">TVA non applicable, art. L. 223 et s. du CIBS</div>
        </div>
        <div style="flex: 1"></div>
        <div style="text-align: right">
          <div>{{ labels.to }}</div>
          <div style="font-size: 16pt">{{ client.company || client.name }}</div>
          <div v-if="client.company && client.name">{{ labels.careOf }} {{ client.name }}</div>
          <div v-if="client.email">{{ client.email }}</div>
          <template v-if="client.address">
            <div v-for="(line, i) in client.address.split(', ')" :key="'cladr_' + i">
              {{ line }}
            </div>
          </template>
          <div v-if="client.phone">{{ client.phone }}</div>
        </div>
      </div>
      <table style="font-size: 10pt; width: 50%; margin: 30pt 0">
        <tr>
          <td>{{ labels.reference }}</td>
          <td>{{ invoice.reference }}</td>
        </tr>
        <tr>
          <td>{{ labels.date }}</td>
          <td>{{ formatDate(new Date(invoice.date)) }}</td>
        </tr>
        <tr v-if="invoice.paymentTermsDays">
          <td>{{ labels.dueDate }}</td>
          <td>{{ paymentDueDate }}</td>
        </tr>
      </table>
      <table style="
          font-size: 11pt;
          border-collapse: collapse;
          border-bottom: 1px solid #d9d9d9;
        ">
        <tr>
          <td style="padding: 4pt; font-weight: bold" colspan="2">
            <span v-if="invoice.description"> {{ invoice.description }}</span>
            <span v-if="invoice.theirReference"> | {{ invoice.theirReference }}</span>
            <span v-if="invoice.jobDates"> | {{ formattedDates }}</span>
          </td>
        </tr>
        <tr v-for="(item, itemIndex) in invoice.items" :key="'item' + itemIndex">
          <td class="item" style="color: #999999; font-size: 10pt">
            {{ item.description }}
          </td>
          <td class="item" style="text-align: right">
            {{ invoice.currency }}{{ formatCurrency(item.rate) }}
          </td>
        </tr>
      </table>
      <table style="
          align-self: flex-end;
          width: 30%;
          font-size: 11pt;
          border-collapse: collapse;
          border-bottom: 1px solid #d9d9d9;
        ">
        <tr v-if="invoice.includeVat">
          <td class="item">{{ labels.subtotal }}</td>
          <td class="item" style="text-align: right;">
            {{ this.invoice.currency + this.formatCurrency(invoiceTotal) }}
          </td>
        </tr>
        <tr v-if="invoice.includeVat">
          <td class="item">{{ labels.vat }} @ 20%</td>
          <td class="item" style="text-align: right;">
            {{ this.invoice.currency + this.formatCurrency(invoiceTotal * 0.2) }}
          </td>
        </tr>
        <tr>
          <td class="item">{{ labels.balance }}</td>
          <td class="item" style="text-align: right; font-weight: bold">
            {{ this.invoice.currency + this.formatCurrency(invoiceTotal * (1 + invoice.includeVat * 0.2)) }}
          </td>
        </tr>
      </table>
      <div style="flex: 1"></div>
      <div style="padding-top: 40pt">
        <table style="font-size: 10pt">
          <tr>
            <td style="padding-top: 20pt" colspan="2">{{ labels.paymentDetails }}</td>
          </tr>
          <tr>
            <td style="width: 140pt">{{ labels.name }}</td>
            <td>{{ state.settings.paymentDetails.name }}</td>
          </tr>
          <template v-if="invoice.paymentMethod === 'French'">
            <tr>
              <td>IBAN</td>
              <td>{{ state.settings.paymentDetails.iban }}</td>
            </tr>
            <tr>
              <td>BIC</td>
              <td>{{ state.settings.paymentDetails.bic }}</td>
            </tr>
            <tr>
              <td>{{ labels.bankAddress }}</td>
              <td>{{ state.settings.paymentDetails.frenchBankName }}, {{ state.settings.paymentDetails.frenchBankAddress
                }}</td>
            </tr>
          </template>
          <template v-if="invoice.paymentMethod === 'UK'">
            <tr>
              <td>Sort code</td>
              <td>{{ state.settings.paymentDetails.sortCode }}</td>
            </tr>
            <tr>
              <td>Account number</td>
              <td>{{ state.settings.paymentDetails.accountNumber }}</td>
            </tr>
            <tr>
              <td>SWIFT</td>
              <td>{{ state.settings.paymentDetails.swift }}</td>
            </tr>
            <tr>
              <td>{{ labels.bankAddress }}</td>
              <td>{{ state.settings.paymentDetails.ukBankName }}, {{ state.settings.paymentDetails.ukBankAddress }}</td>
            </tr>
          </template>
          <template v-if="invoice.paymentTermsDays">
            <tr>
              <td style="padding-top: 20pt" colspan="2">{{ labels.terms }}</td>
            </tr>
            <tr>
              <td colspan="2">{{ labels.termsWording(invoice.paymentTermsDays) }}</td>
            </tr>
          </template>
        </table>
      </div>
    </template>
  </div>
</template>

<script>

import { formatDateList } from "../FormatDates.js";

function uuidv4() {
  return ([1e7] + -1e3 + -4e3 + -8e3 + -1e11).replace(/[018]/g, c =>
    (
      c ^
      (crypto.getRandomValues(new Uint8Array(1))[0] & (15 >> (c / 4)))
    ).toString(16)
  );
}
class Client {
  constructor() {
    this.id = uuidv4();
    this.company = "";
    this.name = "";
    this.email = "";
    this.phone = "";
    this.address = "";
    this.language = "English";
  }
}
export default {
  name: "PrintableInvoice",
  props: {
    state: Object,
    invoice: Object
  },
  methods: {
    formatDate(date) {
      return date.toLocaleDateString(this.locale, {
        year: "numeric",
        month: "long",
        day: "numeric"
      });
    },
    formatCurrency(value) {
      // duplicated in invoices
      if (isNaN(value)) {
        return 0;
      }
      if (parseInt(value) == parseFloat(value)) {
        return value.toString();
      }
      return new Number(value).toFixed(2);
    },
    translate(input) {
      return input[["en-GB", "fr-FR"].indexOf(this.locale)]
    }
  },
  computed: {
    client() {
      return (
        this.state.clients.find(client => client.id === this.invoice.client) ||
        new Client()
      );
    },
    paymentDueDate() {
      let date = new Date(this.invoice.date);
      date.setDate(date.getDate() + Number(this.invoice.paymentTermsDays));
      return this.formatDate(date);
    },
    invoiceTotal() {
      // duplicated in invoices
      const reducer = (accumulator, currentValue) =>
        accumulator + (Number(currentValue.rate) || 0);
      return this.invoice.items.reduce(reducer, 0);
    },
    locale() {
      let client = this.state.clients.find(client => client.id === this.invoice.client)
      if (!client)
        return "en-GB";

      //if(!this || !this.client || !this.client.language) return "en-GB"
      //console.log(this)
      switch (client.language) {
        default: return "en-GB"
        case "French": return "fr-FR"
      }
    },
    formattedDates() {
      return formatDateList(this.invoice.jobDates, this.locale);
    },
    labels() {
      return {
        invoice: this.translate(["Invoice", "Facture"]),
        from: this.translate(["From", "De"]),
        to: this.translate(["To", "À"]),
        careOf: this.translate(["c/o", "À l’attention de"]),
        reference: this.translate(["Invoice reference", "Référence de facture"]),
        date: this.translate(["Invoice date", "Date de facture"]),
        dueDate: this.translate(["Payment due by", "Date limite de paiement"]),
        subtotal: this.translate(["Subtotal", "Sous-total"]),
        vat: this.translate(["VAT", "TVA"]),
        balance: this.translate(["Balance due", "Montant restant dû"]),
        paymentDetails: this.translate(["Payment details", "Modalités de paiement"]),
        name: this.translate(["Account name", "Titulaire du compte"]),
        terms: this.translate(["Terms", "Conditions de paiement"]),
        termsWording: (days) => this.translate([`Please ensure payment is made within ${days} days. Thank you.`, `Règlement à ${days} jours à compter de la date d'émission de la facture. Merci.`]),
        bankAddress: this.translate(["Bank address", "Adresse de la banque"]),
      }
    }
  }
};
</script>

<style scoped>
.page {
  position: absolute;
  top: -10000px;
  display: flex;
  width: 100%;
  height: 100%;
  padding: 2em;
  flex-direction: column;
  font-family: "Montserrat", sans-serif;
  box-sizing: border-box;
}

td {
  padding: 2pt 0;
}

td.item {
  padding: 8pt 4pt;
}

@media print {
  .page {
    top: 0;
    font-family: 'Montserrat', sans-serif !important; 
    font-weight: 300;
  }
}
</style>
